def determining(key):
	if len(key) == 0:
		return 0
	minimum = 0
	for point in range (1, len(key)):
		minimum += 2 ** point
	shift = 1
	for index in range(len(key)):
		if key[index] == "1":
			shift += 2 ** (len(key) - (index + 1))
	return minimum + shift
def lineout():
	print("~" * 60)
def rightPrinting(block):
	scroll = block.split("*n*")
	for line in scroll[:-2]:
		print(line)
	print()
	print(scroll[-1])
	lineout()
def yes_no():
	answer = input()
	yes = True
	no = False
	if len(answer) == 0:
		return yes
	if answer[0] == "Y":
		return yes
	elif answer[0] == "N":
		return no
	else:
		return no
def main(book):			
	input("To answer affirmatively, return any word that begins with Y.\nTo answer negatively to any question, return any word that begins with N.\nReturning nothing counts as a yes; returning anything else counts as a no.\nReturn to start...")
	lineout()
	coordinates = ""
	while True:
		try:
			paragraph = book[determining(coordinates)]
			if paragraph == "...":
				print("You have reached the end of this pathway whose story shall be continued.\nWe will now return from the beginning.\nYou may close the program if you wish not to.")
				input("Return to continue...")
				return None
			rightPrinting(paragraph)
			lineout()
			if yes_no():
				coordinates += "1"
			else:
				coordinates += "0"
		except IndexError:
			print("You have reached the end of this pathway whose story shall be continued.\nWe will now return from the beginning.\nYou may close the program if you wish not to.")
			input("Return to continue...")
			return None
